import{_ as d,o as a,c as r,a3 as n}from"./chunks/framework.bvEHUNtb.js";const b=JSON.parse('{"title":"断占总诀篇之二：万物赋","description":"通过万物、饮食与歌诀，扩展八卦取象与克应的观察范围。","frontmatter":{"title":"断占总诀篇之二：万物赋","description":"通过万物、饮食与歌诀，扩展八卦取象与克应的观察范围。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md","lastUpdated":1786982540000}'),s={name:"yijing/meihua-yishu/duan-zhan-zong-jue/myriad-things-ode.md"};function p(o,t,e,l,i,h){return a(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌" tabindex="-1">【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌 <a class="header-anchor" href="#【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌" aria-label="Permalink to &quot;【断占总诀篇之二】万物赋·饮食篇·观物玄妙歌诀·诸事响应歌&quot;">​</a></h1><blockquote><p>本篇是全书最大的「象意词典」与「断法总歌」，万物赋讲克应取象，饮食篇讲八卦饮食断法，观物玄妙歌诀讲八卦物性，诸事响应歌是全书断法的歌诀总结。</p></blockquote><hr><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="万物赋" tabindex="-1">万物赋 <a class="header-anchor" href="#万物赋" aria-label="Permalink to &quot;万物赋&quot;">​</a></h3><p>人禀阴阳，卦分先后。达时务者，近取诸身，远取诸物。观物理者，静则乎地，动则乎天。原夫万物有数，易数无穷。动静可知，不出于玄天之外。吉凶必见，莫逃乎爻象之中。未成卦以前，必虚心而求应；既成卦以后，复观刻应以为断。声音言语，傍人谶兆，当遇形影往来，我心指实皆是，及其六爻以定，三天既生，始寻卦象之端，终测刻应之理。是以逢吉兆而终知有喜，见凶识而不免乎凶。故欲知他人家之事，必须凭我耳目之闻见。未成卦而闻见之，乃已生之事。既定卦而观察之，乃未来之机。或闻何处喧闹，主有斗争；或听此间笑语，必逢吉庆；见妇啼叹，其家阴小有灾；东至军来，必有官司词讼；或逢枷锁而枷锁临身；倘遇鞭杖而鞭杖必至。若屠而负肉，此为骨肉有灾；倘逢血光，而又恐灾于孳畜。师巫乐饵，病患临门。见诐则有犯家先，逢酒则欠神愿。阴人至则女子有厄，阳人至则男子当灾。又须八卦中分，不可一例而论。卦吉而爻象又吉，祸患终无；卦凶而识兆又凶，灾殃难免。披麻带孝，必然孝服临头；持杖而号，定主号泣满室。其人忧终是为忧，其人喜还须有喜。故当观色察形，以为决意断心。其或鼓乐声喧，又见酒杯器皿，若不迎婚嫁娶，定须会客宴酣。欲知应在何日，须观爻象值数。巽五日而坤八日，离三朝而坎六朝。又观远近克应，以断得买之相期。应远，则全卦相同；应近，而各时同断。假如天地否卦，上天一而下地八；设若泽火革卦，上兑二而下离三。依此推之，万无一失。此人物之兆，察之可推也。及其鸟兽之应，仍验之有准。鹊噪而喜色已动，鸦鸣而祸事将来。牛羊猪犬，日晨不见，金日遇之，六畜有损。木日见猪养猪，必成。庚日见鸡鸣，丁日见羊过，此乃凶刃之杀。己日值马来，壬日猪过，此皆食禄之兆。见吉兆而百事亨通，逢凶谶而诸事阻滞。或若求财问利，须凭克应。以言柜箱为藏财之用，绳索为穿钱之物。逢金帛宝货之类，理必有成。遇刀刃剑具之器，损而无益。又看原卦，不可执一。逢财而有财，无财而无益。凡物成器，方系得全，缺损破碎，有之不足。或问婚姻，理亦相似。物团圆，指日而成；物破损，中逢阻折。此又是一家，闻奥理明，万事昭然。逢柴炭主忧，折麦主悲。米必奇，豆必伤。末与鞋，万事和谐；棋与药，与人期约。斧锯必有修造，粮储必有远行。闻禽鸣，谋事虚说。听鼓声，交易空虚。拭目润睫，内有哭泣之事；持刃见血，外有虫毒之讲。克应既明，饮食同断。见水为饮食酒汤，遇火为煎炮烤炙。见米为一饭之得，提壶为酌杯之礼。水乃鱼暇水中物味，土乃牛羊土内菜蔬。姜面为辛味辣羹，刀砧乃董腥美味。此三天之克应，万物之枢机。能达此者尚其秘之。</p><h3 id="饮食篇" tabindex="-1">饮食篇 <a class="header-anchor" href="#饮食篇" aria-label="Permalink to &quot;饮食篇&quot;">​</a></h3><p>夫干之为象也，圆坚而味辛，取象乎卯，为牲之首，为马为猪，秋得之而食禄盛，夏得之而食禄衰。春为时新之物，水果蔬菜之属；冬为冷物，隔宿之食。有坎乃江湖海味，有水而蔬果珍羞。</p><p>艮为土物同烹，离乃火边煎炙。秋为蟹，春为马。凡内必多肉，其味必辛，盛有瓦器，伴有金樽。其于菜也为芹，其于物也带羽。克生生回，食必鹅鸭。生出克入，野菜无名。</p><p>坤其于坤也，远客至，故人来，所用必瓦器，所食米果之味。静则梨枣茄芋，动则鱼虾鲜羊。无骨肉脯，杀亦为藏，藏亦为肚肠。遇客必妇人，克此必主口舌。克出生回，乃牲之味；克入生物，乃集物之烹。见干、兑，细切薄披；见震、巽而新生旧煮，其色黑黄，其味甘甜，水火并之，蒸炊而已。四时皆为米麦之味，必带麻姜。仔细推详必有验也。</p><p>巽之为卦，主文书柬约之间，讲论之际，外客婚姻，故人旧交。或主远信近期，其色白青，其性曲直，其味酸，其象长。桃李木瓜，斋辣素食，为鱼为鸡，其豆其面，非济执而得之，必锄掘而得之。有干、兑，食之而致病，有坤，得之非难。炊为炒菜蔬，离为炒茶，带坎于中，酒汤其食。其无生，半斋半荤。其在艮也，会邻里，有贵人。食物不多，适口而已。其桔油菜果蔬，斫伐于山林带节，虎狗兔鹿，渔捕网罗，米麻面麦。克入集食，克出羊肉。克入口舌，是非阴灾，极不可食。其味甘甜，其色玄黄。坎为水象也，水近信至海内，味香有细鳞，或四足。凡曰水族，必可饮食也。或闻箫鼓之声，或在礼乐之所，其色黑，其味咸。克出饮酒，回食鱼。为豕为目，为耳为血。羹汤物味，酒食水酱。遇离而说文书，逢干而为海味。</p><p>震之为卦，木属也。酒友疏狂，虚轻怪异。大树之果，园林之蔬，其色青而味酸，其数多，会客少。或有膻臭之气，或有异香之肴。同离多，主盐茶；见坎或为盐醋。</p><p>离则文书交易，亲戚师儒，坐中多礼貌之人，筵上总英才之士。其物乃煎烤炙烧，其间或茶盐。白日之夕，虽之以烛，春夏之际。凡物带花，老人莫食。心事不宁，少者宜之。宜讲论，即有益。为鸡为雉，为蟹为蛇，色赤味苦，性热而气香。逢坎而酒请之争，逢巽则炒菜而已。</p><p>兑之为卦，其属白金，其味辛而色白。或远客暴至，或近交争来。凡动物刀砧，凡味必有辛辣，凡包里腌藏。其于暴也，为菲为菱；其于菜也，为葱为韭。盛而有腥臭，旺而有羊鹅。坐间有潜越之人，或有歌娼之女。单则必然口舌，重则必然欢喜。生出多食，克出好事。</p><p>夫算其饮食，必须察其动静。故动则有，静则无。以体卦下卦为己卦，上为人卦。下为变为客，互之上为酒，下为食物。取象体之下为食何物，变为客体，下食之不终，生体下吉。互克体之不得食。他人克应亦难食。他人生，他人请，己生体生下，己请人。互受生后不计杯杓。上体受生客不计数。变生互，客有后至者；互生克，有先去者。取其日时，以互卦用矣。</p><h3 id="观物玄妙歌诀" tabindex="-1">观物玄妙歌诀 <a class="header-anchor" href="#观物玄妙歌诀" aria-label="Permalink to &quot;观物玄妙歌诀&quot;">​</a></h3><p>观物戏验者，虽云无益于世，学者以此验数，而知圣人作《易》之灵耳。物之于世，必有数焉。故天圆地方，物之形也；天玄地黄，物之色也；天动地静，物之性也；天上地下，物之位也；干刚坤柔，物之体也。故干之为卦，刚而圆，贵而坚，为金为玉，为赤为圆，为大为首，为上之果物。见兑为毁拆，逢坎而沉溺，见离为炼煅之金，震为有动之物，巽为木果为圆，坤、艮土中之石，得火而成器。兑为剑锋之锐，秋得而价高，夏得之而衰矣。</p><p>坤之为卦，其形直而方，其色黑而黄。为文为布，为舆为金。其物象牛，其性恶动。得干乃可圆可方，可贵可贱。震、巽为长器，离为文章，兑为土中出之金，艮为带刚之土石也。</p><p>震之为卦，其色玄黄而多青，为木为声，为竹为萑苇，为蕃鲜及生形。上柔下刚，是性震动而可惊。得干乃为声价之物，得兑为无用之木，见艮山林间之石，见坎有气之类，巽为有枝叶，见离为带花。</p><p>巽之为卦，其色白，其气香。为草木，为刚为柔。见离为文书，见兑、干为不用，乃遇金刀之物。坤、艮为草木之类，坎、兑为可食之物。为长为直，并震而春生夏长，草木之果蔬。</p><p>坎之为卦，其色黑，亦可圆可方物。为柔为腐，内则刚物。得之卑湿之所，多为水中之物。见干亦圆，见兑亦毁。又乃污湿，得震、巽而可食；离、水火既济，假水而出，假火而成。又为滞于物，兑为带口也。震、巽为带枝叶，为带花也。</p><p>离之为卦也，其色黄而青，体燥，其性则上刚下柔。为山石之物，土瓦之类，小石于大山，为门途之处。为物见干而刚，兑而毁折，坤而土块，巽为草之物，而震为木物类也。坎并为河岸之物，离并为瓦器，震、巽并见篱壁之物。</p><p>兑之为卦，其色白，其性少柔多刚。为毁折而下，全带口而圆。见干先圆后缺，见艮则金石废器，见震、巽为剥削之物，见坎为水之类。得干而多刚，得坤而多柔，长于西泽之内。于水中之类，得柔而成器也。</p><h3 id="诸事响应歌" tabindex="-1">诸事响应歌 <a class="header-anchor" href="#诸事响应歌" aria-label="Permalink to &quot;诸事响应歌&quot;">​</a></h3><p>混沌开辟立人极，吉凶回应尤难避。<br> 先贤遗下预知音，《皇极》《观梅》出《周易》。<br> 玄微浩瀚总无涯，各述繁言人莫记。<br> 大抵体宜用卦生，旺相谋为终有益。<br> 比和为吉克为凶，生用亦为凶兆矣。<br> 问雨天晴无坎兑，亢旱言之终则是。<br> 天时连雨问晴明，艮离贲卦回应耳。<br> 干明坤晦巽多风，震主雷霆定莫疑。<br> 凡占人事体克用，诸事亨通须有幸。<br> 比和为妙克为凶，又看其中体卦证。<br> 干主公门是老人，坤遇阴人曰土应。<br> 震为东方或山林，巽亦山林蔬果品。<br> 坎为北方并水姓，酒货鱼盐才取定。<br> 离言文书炉冶利，亦日南方颜色亦。<br> 艮为东北山林材，兑曰西方喜悦是。<br> 生体克体亦同方，编记以为诸事应。<br> 凡问家宅体为主，旺相须知进田土。<br> 生用须云耗散财，比和家世安居处。<br> 克体为凶决断之，生产以体为其母。<br> 两宜生旺不宜衰，奇偶之中察男女。<br> 干卦为阳坤为阴，又有来人爻内取。<br> 阴多生女阳生男，此数分明具易理。<br> 婚姻生用必难成，比和克用大吉利。<br> 若问饮食和生体，必知肴馔丰厚喜。<br> 生用克体饮食难，克用必无比和美。<br> 坎兑为酒震为鱼，八卦推求衰旺取。<br> 求谋称意是比和，克用谋为迟可已。<br> 求名克用名可求，生体比和俱可取。<br> 求财克用日有财，生体比和俱称意。<br> 交易生体及比和，有利必成无后虑。<br> 出行克用用生体，所至其方多得意。<br> 坎则乘舟离旱途，干震动则坤艮止。<br> 行人克用必来迟，生体比和人即至。<br> 成远恒迟升不回，艮阻坎险君须记。<br> 若去谒人体克用，速可追寻依卦断。<br> 相生比和终可寻，兑临残缺并井畔。<br> 离为冶所及南方，坤主方器凭推看。<br> 疾病最宜体旺相，克用易安药有效。<br> 比和凶则有救星，体卦受克为凶兆。<br> 离宜服热坎服冷，卦见坤土温补亨。<br> 亦把鬼神卦象推，震主娇怪为状貌。<br> 巽为自缢井锁枷，坤艮落水及血刃。<br> 凡占公讼用宜克，体卦旺相终得理。<br> 比和助解最为奇，非止全仗他人力。<br> 若问墓穴在何地，坤则平阳巽林里。<br> 干宜高葬艮临山，离近人烟兑兴废。<br> 比和生体宜葬之，克用尤为大吉利。<br> 若人临问听傍言，笑语鸡鸣亦吉美。<br> 美物是为祥端推，略举片言通万类。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>禀</td><td>bǐng</td><td>承受，禀受</td></tr><tr><td>谶兆</td><td>chèn zhào</td><td>预兆，应验的征兆</td></tr><tr><td>刻应</td><td>kè yìng</td><td>克期应验，在特定时间节点应验</td></tr><tr><td>孳畜</td><td>zī chù</td><td>牲畜，孳：繁殖</td></tr><tr><td>师巫乐饵</td><td>wū</td><td>巫师·乐师·药饵，主病患</td></tr><tr><td>诐</td><td>bì</td><td>邪僻，见诐：见到邪僻之人或物</td></tr><tr><td>披麻带孝</td><td>—</td><td>穿孝服，主丧事</td></tr><tr><td>刀砧</td><td>zhēn</td><td>砧板，刀砧：厨刀与砧板，主荤腥美味</td></tr><tr><td>萑苇</td><td>huán wěi</td><td>芦苇类植物</td></tr><tr><td>蕃鲜</td><td>fān xiān</td><td>茂盛鲜嫩之物</td></tr><tr><td>卑湿</td><td>bēi shī</td><td>低洼潮湿之地</td></tr><tr><td>枢机</td><td>shū jī</td><td>关键·核心，枢：门轴</td></tr><tr><td>亢旱</td><td>kàng hàn</td><td>极度干旱</td></tr><tr><td>贲卦</td><td>bì guà</td><td>山火贲，艮上离下，主文饰·晴明</td></tr><tr><td>肴馔</td><td>yáo zhuàn</td><td>丰盛的菜肴</td></tr><tr><td>谒人</td><td>yè rén</td><td>拜访·求见他人</td></tr><tr><td>冶所</td><td>yě suǒ</td><td>冶炼之所，铁匠铺·炉灶处</td></tr><tr><td>杯杓</td><td>bēi sháo</td><td>杯与勺，泛指饮食器具</td></tr><tr><td>柬约</td><td>jiǎn yuē</td><td>书信·约定</td></tr><tr><td>疏狂</td><td>shū kuáng</td><td>放荡不羁</td></tr></tbody></table><hr><h2 id="📖-白话译文" tabindex="-1">📖 白话译文 <a class="header-anchor" href="#📖-白话译文" aria-label="Permalink to &quot;📖 白话译文&quot;">​</a></h2><h3 id="万物赋-译" tabindex="-1">万物赋（译） <a class="header-anchor" href="#万物赋-译" aria-label="Permalink to &quot;万物赋（译）&quot;">​</a></h3><p>人禀受阴阳之气，卦分先天后天。通达时务者，近取诸身，远取诸物。观察物理者，静则法地，动则法天。万物皆有数，易数无穷。动静可以知晓，不出玄天之外。吉凶必然显现，莫逃于爻象之中。</p><p><strong>起卦前后的两个阶段</strong>：</p><ul><li>未成卦之前：虚心求应（感受环境中的象）</li><li>既成卦之后：观克应以为断（用卦象印证所见）</li></ul><p>未成卦而闻见之 → 已生之事（已经发生的）<br> 既定卦而观察之 → 未来之机（将要发生的）</p><p><strong>克应取象对照表</strong>（万物赋核心）：</p><table tabindex="0"><thead><tr><th>所见所闻</th><th>克应断语</th></tr></thead><tbody><tr><td>喧闹声</td><td>主斗争</td></tr><tr><td>笑语声</td><td>必逢吉庆</td></tr><tr><td>妇人啼叹</td><td>家中阴小有灾</td></tr><tr><td>东方有军来</td><td>必有官司词讼</td></tr><tr><td>枷锁</td><td>枷锁临身</td></tr><tr><td>鞭杖</td><td>鞭杖必至</td></tr><tr><td>屠夫负肉</td><td>骨肉有灾</td></tr><tr><td>血光</td><td>恐灾于牲畜</td></tr><tr><td>师巫乐饵</td><td>病患临门</td></tr><tr><td>见邪僻之人</td><td>犯家先（冲犯祖先）</td></tr><tr><td>逢酒</td><td>欠神愿（许愿未还）</td></tr><tr><td>阴人至</td><td>女子有厄</td></tr><tr><td>阳人至</td><td>男子当灾</td></tr><tr><td>披麻带孝</td><td>孝服临头</td></tr><tr><td>持杖而号</td><td>号泣满室</td></tr><tr><td>鼓乐·酒杯器皿</td><td>迎婚嫁娶或宴客</td></tr><tr><td>柴炭</td><td>主忧</td></tr><tr><td>折麦</td><td>主悲</td></tr><tr><td>米</td><td>必奇（有奇遇）</td></tr><tr><td>豆</td><td>必伤</td></tr><tr><td>鞋·末（鞋底）</td><td>万事和谐</td></tr><tr><td>棋·药</td><td>与人期约</td></tr><tr><td>斧锯</td><td>必有修造</td></tr><tr><td>粮储</td><td>必有远行</td></tr><tr><td>禽鸣</td><td>谋事虚说（空谈）</td></tr><tr><td>鼓声</td><td>交易空虚</td></tr><tr><td>拭目润睫</td><td>内有哭泣之事</td></tr><tr><td>持刃见血</td><td>外有虫毒之患</td></tr><tr><td>鹊噪</td><td>喜色已动</td></tr><tr><td>鸦鸣</td><td>祸事将来</td></tr><tr><td>柜箱</td><td>藏财，求财有成</td></tr><tr><td>绳索</td><td>穿钱之物，财有望</td></tr><tr><td>金帛宝货</td><td>必有成</td></tr><tr><td>刀刃剑具</td><td>损而无益</td></tr><tr><td>物团圆完整</td><td>婚姻·事成</td></tr><tr><td>物破损缺碎</td><td>婚姻·事有阻折</td></tr></tbody></table><p><strong>应期推算</strong>：</p><ul><li>巽 → 五日；坤 → 八日；离 → 三朝；坎 → 六朝</li><li>应远 → 全卦数合算；应近 → 各卦时序分断</li><li>天地否：上乾一·下坤八；泽火革：上兑二·下离三</li></ul><p><strong>禽兽克应</strong>：</p><ul><li>庚日见鸡鸣·丁日见羊过 → 凶刃之杀</li><li>己日值马来·壬日猪过 → 食禄之兆</li><li>木日见猪·养猪必成</li></ul><p><strong>饮食克应</strong>：</p><ul><li>水 → 饮食酒汤；火 → 煎炮烤炙</li><li>米 → 一饭之得；提壶 → 酌杯之礼</li><li>水 → 鱼虾水中物；土 → 牛羊菜蔬</li><li>姜面 → 辛味辣羹；刀砧 → 荤腥美味</li></ul><h3 id="饮食篇-各卦饮食象意" tabindex="-1">饮食篇（各卦饮食象意） <a class="header-anchor" href="#饮食篇-各卦饮食象意" aria-label="Permalink to &quot;饮食篇（各卦饮食象意）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卦</th><th>饮食特征</th><th>时令</th><th>味</th><th>器皿</th><th>特殊情况</th></tr></thead><tbody><tr><td><strong>乾</strong></td><td>圆坚辛味，马猪牲首</td><td>秋盛·夏衰·春时新·冬冷食</td><td>辛</td><td>金樽</td><td>有坎→海味；有水→珍羞</td></tr><tr><td><strong>艮</strong></td><td>土物同烹，火边煎炙</td><td>秋蟹·春马</td><td>辛</td><td>瓦器</td><td>带羽之物，克生→鹅鸭</td></tr><tr><td><strong>坤</strong></td><td>米果之味，远客故人</td><td>静→梨枣茄芋；动→鱼虾鲜羊</td><td>甘甜</td><td>瓦器</td><td>见乾兑→细切薄片；见震巽→新生旧煮</td></tr><tr><td><strong>巽</strong></td><td>素食酸味，桃李木瓜</td><td>—</td><td>酸·甘甜</td><td>—</td><td>有乾兑→食之致病；有坤→易得；带坎→酒汤</td></tr><tr><td><strong>坎</strong></td><td>水族海味，细鳞四足</td><td>—</td><td>咸·香</td><td>—</td><td>遇离→说文书；逢乾→海味；克出→饮酒</td></tr><tr><td><strong>震</strong></td><td>园林蔬果，酒友疏狂</td><td>—</td><td>酸</td><td>—</td><td>同离→盐茶；见坎→盐醋；膻臭或异香</td></tr><tr><td><strong>离</strong></td><td>煎烤炙烧，亲戚师儒</td><td>春夏带花</td><td>苦·香</td><td>—</td><td>逢坎→酒争；逢巽→炒菜；老人莫食</td></tr><tr><td><strong>兑</strong></td><td>辛辣腌藏，葱韭菱菲</td><td>—</td><td>辛</td><td>—</td><td>旺→羊鹅；单→口舌；重→欢喜；生出→多食</td></tr></tbody></table><p><strong>饮食动静总诀</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>动则有食，静则无食</span></span>
<span class="line"><span>下卦（体）= 己方；上卦 = 人方</span></span>
<span class="line"><span>互卦上 = 酒；互卦下 = 食物</span></span>
<span class="line"><span>变卦 = 客体（来客情况）</span></span>
<span class="line"><span>生体下 → 吉（己方有食）</span></span>
<span class="line"><span>互克体 → 不得食</span></span>
<span class="line"><span>他人生 → 他人请客</span></span>
<span class="line"><span>己生体生下 → 己请人</span></span>
<span class="line"><span>变生互 → 客有后至者</span></span>
<span class="line"><span>互生克 → 有先去者</span></span></code></pre></div><h3 id="观物玄妙歌诀-八卦物性总表" tabindex="-1">观物玄妙歌诀（八卦物性总表） <a class="header-anchor" href="#观物玄妙歌诀-八卦物性总表" aria-label="Permalink to &quot;观物玄妙歌诀（八卦物性总表）&quot;">​</a></h3><p><strong>天地基本象</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天圆地方 = 物之形</span></span>
<span class="line"><span>天玄地黄 = 物之色</span></span>
<span class="line"><span>天动地静 = 物之性</span></span>
<span class="line"><span>天上地下 = 物之位</span></span>
<span class="line"><span>乾刚坤柔 = 物之体</span></span></code></pre></div><p><strong>八卦物性详表</strong>：</p><table tabindex="0"><thead><tr><th>卦</th><th>形</th><th>色</th><th>性</th><th>遇他卦变化</th></tr></thead><tbody><tr><td><strong>乾</strong></td><td>圆·坚</td><td>赤</td><td>刚·贵</td><td>见兑→毁折；逢坎→沉溺；见离→炼金；见震→动物；见巽→木果圆；见坤艮→土中之石</td></tr><tr><td><strong>坤</strong></td><td>方·直</td><td>黑黄</td><td>柔·恶动</td><td>得乾→可圆可方；见震巽→长器；见离→文章；见兑→土中金；见艮→带刚土石</td></tr><tr><td><strong>震</strong></td><td>上柔下刚</td><td>玄黄多青</td><td>动·惊</td><td>得乾→声价之物；得兑→无用之木；见艮→山林石；见坎→有气之类；见巽→有枝叶；见离→带花</td></tr><tr><td><strong>巽</strong></td><td>长·直</td><td>白</td><td>香·曲直</td><td>见离→文书；见兑乾→遇金刀不用；见坤艮→草木；见坎兑→可食之物</td></tr><tr><td><strong>坎</strong></td><td>圆或方</td><td>黑</td><td>柔·腐·内刚</td><td>见乾→亦圆；见兑→亦毁；得震巽→可食；见离→水火既济；见兑→带口；见震巽→带枝叶带花</td></tr><tr><td><strong>离</strong></td><td>—</td><td>黄青</td><td>上刚下柔·燥</td><td>见乾→刚；见兑→毁折；见坤→土块；见巽→草物；见震→木物；见坎→河岸之物；见离→瓦器；见震巽→篱壁之物</td></tr><tr><td><strong>兑</strong></td><td>带口·圆</td><td>白</td><td>少柔多刚·毁折</td><td>见乾→先圆后缺；见艮→金石废器；见震巽→剥削之物；见坎→水之类；得乾→多刚；得坤→多柔</td></tr></tbody></table><h3 id="诸事响应歌-各事断法总诀" tabindex="-1">诸事响应歌（各事断法总诀） <a class="header-anchor" href="#诸事响应歌-各事断法总诀" aria-label="Permalink to &quot;诸事响应歌（各事断法总诀）&quot;">​</a></h3><p><strong>总纲</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>体宜用卦生 → 旺相谋为有益</span></span>
<span class="line"><span>比和为吉，克为凶</span></span>
<span class="line"><span>生用（体生用）→ 亦为凶兆（泄气）</span></span></code></pre></div><p><strong>各事断法速查表</strong>：</p><table tabindex="0"><thead><tr><th>占问之事</th><th>吉断</th><th>凶断</th><th>特殊</th></tr></thead><tbody><tr><td><strong>天时·雨</strong></td><td>有坎兑</td><td>无坎兑→亢旱</td><td>—</td></tr><tr><td><strong>天时·晴</strong></td><td>艮·离·贲卦</td><td>—</td><td>乾明·坤晦·巽风·震雷</td></tr><tr><td><strong>人事</strong></td><td>体克用，诸事亨通</td><td>克体为凶</td><td>—</td></tr><tr><td><strong>家宅</strong></td><td>旺相→进田土；比和→安居</td><td>克体→凶</td><td>生用→耗散财</td></tr><tr><td><strong>生产</strong></td><td>体旺生旺，奇爻→男，偶爻→女</td><td>体衰</td><td>阴多→女，阳多→男</td></tr><tr><td><strong>婚姻</strong></td><td>比和·克用→大吉利</td><td>生用→难成</td><td>—</td></tr><tr><td><strong>饮食</strong></td><td>生体→丰厚</td><td>生用克体→饮食难</td><td>克用→无；比和→美</td></tr><tr><td><strong>求谋</strong></td><td>比和→称意</td><td>—</td><td>克用→迟可已</td></tr><tr><td><strong>求名</strong></td><td>克用·生体·比和→可取</td><td>—</td><td>—</td></tr><tr><td><strong>求财</strong></td><td>克用·生体·比和→称意</td><td>—</td><td>—</td></tr><tr><td><strong>交易</strong></td><td>生体·比和→有利必成</td><td>—</td><td>—</td></tr><tr><td><strong>出行</strong></td><td>克用·用生体→得意</td><td>—</td><td>坎→乘舟；离→旱途；乾震→动；坤艮→止</td></tr><tr><td><strong>行人</strong></td><td>生体·比和→人即至</td><td>克用→来迟</td><td>恒→迟；升→不回；艮→阻；坎→险</td></tr><tr><td><strong>谒见</strong></td><td>相生比和→可寻</td><td>—</td><td>兑→残缺井畔；离→冶所南方；坤→方器</td></tr><tr><td><strong>疾病</strong></td><td>体旺相·克用→易安有效</td><td>体受克→凶兆</td><td>离→服热药；坎→服冷药；坤→温补</td></tr><tr><td><strong>鬼神</strong></td><td>—</td><td>—</td><td>震→娇怪；巽→自缢井锁枷；坤艮→落水血刃</td></tr><tr><td><strong>公讼</strong></td><td>用宜克·体旺相→得理；比和→助解</td><td>—</td><td>—</td></tr><tr><td><strong>墓穴</strong></td><td>比和生体→宜葬；克用→大吉</td><td>—</td><td>坤→平阳；巽→林里；乾→高葬；艮→临山；离→近人烟；兑→兴废之地</td></tr></tbody></table><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、万物赋-起卦前后的两个世界" tabindex="-1">一、万物赋：起卦前后的两个世界 <a class="header-anchor" href="#一、万物赋-起卦前后的两个世界" aria-label="Permalink to &quot;一、万物赋：起卦前后的两个世界&quot;">​</a></h3><p>万物赋开篇有一句极重要的话，把占卜分成了两个阶段：</p><blockquote><p>未成卦而闻见之，乃<strong>已生之事</strong>。既定卦而观察之，乃<strong>未来之机</strong>。</p></blockquote><p>这两个阶段的逻辑完全不同：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>起卦前所见所闻 → 已经发生的事实（印证当下）</span></span>
<span class="line"><span>起卦后所见所闻 → 将要发生的预兆（预测未来）</span></span></code></pre></div><p>这与三要灵应篇的「未占先看三要」完全呼应——起卦前的感知，是对「已然」的确认；起卦后的感知，是对「未然」的预测。两者合参，才是完整的占断。</p><h3 id="二、克应取象-象的语言是具体的" tabindex="-1">二、克应取象：象的语言是具体的 <a class="header-anchor" href="#二、克应取象-象的语言是具体的" aria-label="Permalink to &quot;二、克应取象：象的语言是具体的&quot;">​</a></h3><p>万物赋列出了大量具体的克应对照，看似繁杂，但背后有清晰的逻辑：</p><p><strong>第一类：直接象征</strong><br> 枷锁→枷锁临身，鞭杖→鞭杖必至。象与应是<strong>同类直接对应</strong>，最简单。</p><p><strong>第二类：五行推演</strong><br> 血光→灾于牲畜（血属坎，坎为豕，牲畜受灾）。象通过五行属性推演到结果。</p><p><strong>第三类：谐音·文化意象</strong><br> 鞋（末）→万事和谐（鞋=谐），棋·药→与人期约（期=约）。这与洞玄歌的梨=离逻辑完全一致。</p><p><strong>第四类：动静判断</strong><br> 禽鸣→谋事虚说，鼓声→交易空虚。动物·声音的象，主事情的虚实。</p><h3 id="三、饮食篇-体用动静在饮食中的应用" tabindex="-1">三、饮食篇：体用动静在饮食中的应用 <a class="header-anchor" href="#三、饮食篇-体用动静在饮食中的应用" aria-label="Permalink to &quot;三、饮食篇：体用动静在饮食中的应用&quot;">​</a></h3><p>饮食篇末尾的总诀，是体用动静理论在「饮食占」这个具体场景中的完整应用：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>动则有食，静则无食</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>下卦（体·己方）= 我</span></span>
<span class="line"><span>上卦（用·人方）= 他人</span></span>
<span class="line"><span>互卦上 = 酒</span></span>
<span class="line"><span>互卦下 = 食物</span></span>
<span class="line"><span>变卦 = 来客情况</span></span></code></pre></div><p>这个框架把一顿饭的全部要素（谁请·喝什么·吃什么·有没有客人）都纳入了卦象，是体用理论最生活化的应用。</p><h3 id="四、观物玄妙歌诀-象的「组合逻辑」" tabindex="-1">四、观物玄妙歌诀：象的「组合逻辑」 <a class="header-anchor" href="#四、观物玄妙歌诀-象的「组合逻辑」" aria-label="Permalink to &quot;四、观物玄妙歌诀：象的「组合逻辑」&quot;">​</a></h3><p>观物玄妙歌诀的核心，是<strong>单卦遇他卦时象意的变化</strong>。</p><p>比如乾卦：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾单独 → 圆·坚·金·玉</span></span>
<span class="line"><span>乾见兑 → 毁折（兑为毁折，金器破损）</span></span>
<span class="line"><span>乾见离 → 炼煅之金（火炼金，成器）</span></span>
<span class="line"><span>乾见坎 → 沉溺（金沉水中）</span></span>
<span class="line"><span>乾见震 → 有动之物（金属动器）</span></span></code></pre></div><p>同一个乾卦，遇到不同的卦，象意完全不同。这说明：<strong>象不是孤立的，是在关系中生成的</strong>。单看一个卦的象意，只是起点；看它与其他卦的关系，才是真正的断卦。</p><h3 id="五、诸事响应歌-全书断法的歌诀化" tabindex="-1">五、诸事响应歌：全书断法的歌诀化 <a class="header-anchor" href="#五、诸事响应歌-全书断法的歌诀化" aria-label="Permalink to &quot;五、诸事响应歌：全书断法的歌诀化&quot;">​</a></h3><p>诸事响应歌是全书断法的「速查手册」，把各类占问的吉凶规律压缩成歌诀。</p><p>有几个特别值得注意的规律：</p><p><strong>「生用亦为凶兆」</strong>：</p><blockquote><p>「比和为吉克为凶，生用亦为凶兆矣。」</p></blockquote><p>体生用 = 泄气，这是凶。这与篇之一「体用总诀」完全一致，在此处歌诀化，方便记忆。</p><p><strong>婚姻的特殊逻辑</strong>：</p><blockquote><p>「婚姻生用必难成，比和克用大吉利。」</p></blockquote><p>婚姻占中，<strong>克用反而吉</strong>——体克用，说明己方能主导，婚姻可成。这与一般占卜「克为凶」不同，是婚姻占的特殊规则。</p><p><strong>疾病的用药逻辑</strong>：</p><blockquote><p>「离宜服热，坎服冷，卦见坤土温补亨。」</p></blockquote><p>卦象直接指向用药方向，离（火）→热药，坎（水）→冷药，坤（土）→温补。这是卦象与医理的直接对应。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="万物赋-每一个当下都在说话" tabindex="-1">万物赋：每一个当下都在说话 <a class="header-anchor" href="#万物赋-每一个当下都在说话" aria-label="Permalink to &quot;万物赋：每一个当下都在说话&quot;">​</a></h3><p>「未成卦而闻见之，乃已生之事。」</p><p>这句话让我感受到：<strong>现实本身就是最诚实的卦</strong>。起卦之前，眼睛看到的、耳朵听到的，已经在告诉你答案了。卦，只是把这个答案系统化。</p><p>如果起卦前就听到哭声，不用等卦来告诉你有悲事——悲事已经在了。卦的作用，是告诉你这个悲事的走向和时间。</p><h3 id="饮食篇-一顿饭里有整个世界" tabindex="-1">饮食篇：一顿饭里有整个世界 <a class="header-anchor" href="#饮食篇-一顿饭里有整个世界" aria-label="Permalink to &quot;饮食篇：一顿饭里有整个世界&quot;">​</a></h3><p>饮食篇让我感受到：<strong>梅花易数的象，细腻到可以断一顿饭</strong>。</p><p>谁请客、喝什么酒、吃什么菜、有没有人中途离席——这些都在卦里。</p><p>这不是炫技，而是说明：<strong>象是无处不在的，大到生死，小到一顿饭，都是同一套象的语言</strong>。能读懂一顿饭的象，就能读懂人生的象。</p><h3 id="观物玄妙歌诀-象在关系中生成" tabindex="-1">观物玄妙歌诀：象在关系中生成 <a class="header-anchor" href="#观物玄妙歌诀-象在关系中生成" aria-label="Permalink to &quot;观物玄妙歌诀：象在关系中生成&quot;">​</a></h3><p>乾见兑是毁折，乾见离是炼金——同一个乾，遇到不同的卦，完全不同。</p><p>这让我感受到：<strong>任何事物的意义，都是在关系中生成的</strong>。孤立地看一件事，只能看到它的本质；看它与周围的关系，才能看到它的命运。</p><p>这不只是易理，也是生活的真相。</p><h3 id="诸事响应歌-婚姻占的「克用为吉」" tabindex="-1">诸事响应歌：婚姻占的「克用为吉」 <a class="header-anchor" href="#诸事响应歌-婚姻占的「克用为吉」" aria-label="Permalink to &quot;诸事响应歌：婚姻占的「克用为吉」&quot;">​</a></h3><p>「婚姻生用必难成，比和克用大吉利。」</p><p>这句话让我停下来想了很久。为什么婚姻占里克用反而吉？</p><p>因为婚姻不是「顺着对方」，而是「能主导这段关系」。体克用，说明我有能力驾驭这段关系，婚姻才能稳固。一味生用（顺着对方），反而会耗散自己，最终难成。</p><p>这是梅花易数里少有的「反常识」规则，背后藏着很深的人生智慧。</p><p>所以说要根据实际的事情来断，不可先入为主套公式。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>万物赋：起卦前所见=已生之事；起卦后所见=未来之机</li><li>克应三类：直接象征·五行推演·谐音文化意象</li><li>应期：巽五日·坤八日·离三朝·坎六朝；全卦数合算远应，各卦时序断近应</li><li>饮食动静：动则有食·静则无食；下卦=己·上卦=人·互上=酒·互下=食·变=客</li><li>观物玄妙：象在关系中生成，单卦遇他卦，象意随之变化</li><li>诸事响应歌：生用为凶（泄气）；婚姻克用为吉（能主导）；疾病离→热药·坎→冷药·坤→温补</li></ul><p><strong>规律提炼</strong></p><ol><li>起卦前后是两个世界：前者印证已然，后者预测未然</li><li>克应取象有三种逻辑：直接象征·五行推演·谐音意象，不可执一</li><li>象是在关系中生成的，单卦象意只是起点，与他卦的关系才是断卦的核心</li><li>饮食占是体用动静理论的生活化应用，框架与其他占问完全一致</li><li>婚姻占「克用为吉」是全书少有的反常识规则，体克用=能主导关系</li><li>疾病占卦象直接指向用药方向，离热·坎冷·坤温补</li></ol><p><strong>与前文呼应</strong></p><ul><li>篇之三「三要灵应·未占先看三要」→ 万物赋「未成卦而闻见之」：同一逻辑的系统化</li><li>篇之五「洞玄歌·植物谐音象意」→ 万物赋「鞋=谐·棋药=期约」：谐音取象贯穿全书</li><li>篇之一「体用动静之诀」→ 饮食篇「动则有食·静则无食」：动静原则在饮食占的应用</li><li>篇之一「体用互变之诀·用最紧·互次之·变又次之」→ 饮食篇「互上=酒·互下=食·变=客」：同一框架</li><li>篇之一「体用衰旺之诀」→ 诸事响应歌各条：衰旺原则在各类占问中的具体化</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-024</strong>：万物赋「应远，则全卦相同；应近，而各时同断。假如天地否卦，上天一而下地八；设若泽火革卦，上兑二而下离三」——这里「全卦相同」指的是上下卦数字相加（否卦：1+8=9日？）还是分别取上下卦数字（1日·8日分别应验）？原文说「依此推之，万无一失」，但计算方式未明述。推测：应远则取全卦数之和为期（否卦1+8=9），应近则分别取上下卦数为期（上卦1日·下卦8日）。待后续章节印证。</p></blockquote><blockquote><p><strong>❓****-025</strong>：饮食篇「艮为土物同烹，离乃火边煎炙。秋为蟹，春为马」——此处「春为马」是指乾卦（乾为马）在春季的饮食象，还是艮卦在春季的象？上下文衔接不够清晰，存疑。</p></blockquote><blockquote><p><strong>❓****-026</strong>：诸事响应歌「成远恒迟升不回」——「成」指地风升之「升」？还是另有所指？「恒迟」指雷风恒卦主迟？「升不回」指地风升卦主远行不归？此处卦名与断语的对应关系需结合卷二行人占案例印证。</p></blockquote>`,125)])])}const c=d(s,[["render",p]]);export{b as __pageData,c as default};
